'use strict';
const assert = require('node:assert/strict');
const { RangeTree } = require('./src/range-tree');
let seed = 12345;
const rnd = (n) => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed % n; };
for (let t = 0; t < 3000; t++) {
  const n = 1 + rnd(20);
  const ref = Array.from({ length: n }, () => rnd(41) - 20);
  const tree = new RangeTree(ref);
  for (let k = 0; k < 60; k++) {
    const a = rnd(n + 1), b = rnd(n + 1), l = Math.min(a, b), r = Math.max(a, b);
    const v = rnd(41) - 20;
    switch (rnd(6)) {
      case 0: tree.assign(l, r, v); for (let i = l; i < r; i++) ref[i] = v; break;
      case 1: tree.add(l, r, v); for (let i = l; i < r; i++) ref[i] += v; break;
      case 2: { let s = 0; for (let i = l; i < r; i++) s += ref[i]; assert.equal(tree.sum(l, r), s); break; }
      case 3: assert.equal(tree.max(l, r), Math.max(-Infinity, ...ref.slice(l, r))); break;
      case 4: { let e = -1; for (let i = l; i < n; i++) if (ref[i] >= v) { e = i; break; } assert.equal(tree.firstAtLeast(l, v), e); break; }
      case 5: if (l < n) assert.equal(tree.get(l), ref[l]); assert.deepEqual(tree.toArray(), ref); break;
    }
  }
}
console.log('fuzz ok');
